pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // 1. Keep the amount in a wide admissible domain: >0 so there is something to withdraw
        amount = bound(amount, 1, 1000 ether);
        // 2. Fund the contract via the fallback; use a separate EOA to avoid mixing balances
        address donor = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(donor != c.owner());
        vm.deal(donor, amount);
        vm.prank(donor);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "donation failed");
        // Record owner's balance and contract's balance before withdrawAll
        uint256 ownerBalBefore = c.owner().balance;
        uint256 contractBalBefore = address(c).balance;
        // 3. Owner calls withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();
        // After the call, the contract's balance decrease must equal the owner's balance increase
        uint256 ownerBalIncrease = c.owner().balance - ownerBalBefore;
        uint256 contractBalDecrease = contractBalBefore - address(c).balance;
        assertTrue(ownerBalIncrease == contractBalDecrease);
    }
}

