import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Restrict depositAmount to [1, type(uint120).max] to avoid infinite debt of vm.deal, but keep wide
        bound(depositAmount, 1, type(uint120).max);
        // Setup: fund the contract with depositAmount
        vm.deal(address(this), depositAmount);
        address(c).call{value: depositAmount}("");
        // Record contract balance before withdrawAll
        uint256 balanceBefore = address(c).balance;
        // Owner balance before
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        // Owner calls withdrawAll
        vm.prank(owner);
        try c.withdrawAll() { } catch { }
        // Contract balance after
        uint256 balanceAfter = address(c).balance;
        // Amount the owner received
        uint256 ownerReceived = owner.balance - ownerBalanceBefore;
        // General invariant: the contract's balance must decrease by exactly the amount the owner received
        // i.e., balanceAfter == balanceBefore - ownerReceived
        // If c is buggy and balanceBefore > 1, ownerReceived == 1 but balanceAfter > 0, so this fails.
        // If c is correct, ownerReceived == balanceBefore, balanceAfter == 0, and invariant holds.
        assertEq(balanceAfter, balanceBefore - ownerReceived, "balance decrease must equal amount transferred to owner");
    }
}

